  -- p0 [text L0] In the Mahabharata, the great Hindu epic, five princes were being taught to fire a bow by a guru 
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"In the Mahabharata, the great Hindu epic, five princes were being taught to fire a bow by a guru (teacher). Each prince was called to stand before the guru and take aim at a bird perched upon a tree branch some distance away."}]}$ob$::jsonb, $ob$In the Mahabharata, the great Hindu epic, five princes were being taught to fire a bow by a guru (teacher). Each prince was called to stand before the guru and take aim at a bird perched upon a tree…$ob$, 0, false, NULL, NULL, false, 0);
  -- p1 [figure 1] Figure 1. The guru and princes by Nandalal Bose
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"figure_placeholder","number":1,"caption":"The guru and princes by Nandalal Bose"},{"type":"text","content":". The guru and princes by Nandalal Bose"}]}$ob$::jsonb, $ob$Figure 1. The guru and princes by Nandalal Bose$ob$, 1, true, v_fig_1, 'auto', false, 0);
  -- p2 [text L0] The guru asked each, “tell me what you see”. The eldest, often depicted as the wisest, describes 
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"The guru asked each, “tell me what you see”. The eldest, often depicted as the wisest, describes the tree and its shadow, the location of the bird within the tangle of branches, and is suddenly interrupted by the guru who tells him to stand back with the others. The next of the five, depicted as the strongest, takes his stance, and when asked, describes the bird and its features but is asked to stand back as well. The next two follow suit and are quickly returned without taking a shot. Finally, the last prince is called to aim and asked what he sees. He tells the guru that he sees a dark sphere. Eyebrows raised, the guru says “are you sure?”, to which the prince says if he tries, he can see a fringe of color surrounding the sphere but nothing else. He is describing the eye of the bird and notices nothing else in the rich scene before him. The guru waved his approval, the arrow fired, and the target struck."}]}$ob$::jsonb, $ob$The guru asked each, “tell me what you see”. The eldest, often depicted as the wisest, describes the tree and its shadow, the location of the bird within the tangle of branches, and is suddenly…$ob$, 2, false, NULL, NULL, false, 0);
  -- p3 [text L0] This story and many others illustrate a series of fundamental puzzles of cognition: Why can we on
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"This story and many others illustrate a series of fundamental puzzles of cognition: Why can we only fully perceive one thing at a time, even though our eyes (or ears, nose, tongue, and skin) take it all in at once? Why do different people (or animals) see the same scene in different ways? Why does perceiving one thing well make the rest fall away? The answer is attention, and decades of study reveal that it allows the brain to focus on the most important information to the task at hand."}]}$ob$::jsonb, $ob$This story and many others illustrate a series of fundamental puzzles of cognition: Why can we only fully perceive one thing at a time, even though our eyes (or ears, nose, tongue, and skin) take it…$ob$, 3, false, NULL, NULL, false, 0);

  -- Section 1: The story of attention
  v_section_id := gen_random_uuid();
  INSERT INTO sections (id, module_id, title, slug, order_index, introduction_text)
  VALUES (v_section_id, v_module_id, $ob$The story of attention$ob$, $ob$the-story-of-attention$ob$, 1, NULL);
  -- p0 [text L0] Hundreds of years after the princes and the bird, the most influential philosophers writing in En
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Hundreds of years after the princes and the bird, the most influential philosophers writing in English had given attention almost nothing to do. Locke, Hume, Hartley, and other great empiricists built the mind out of sensation and association alone[ref]. These writers saw the mind as a passive recipient of experience, shaped entirely by what fell upon the senses from outside."}]}$ob$::jsonb, $ob$Hundreds of years after the princes and the bird, the most influential philosophers writing in English had given attention almost nothing to do. Locke, Hume, Hartley, and other great empiricists…$ob$, 0, false, NULL, NULL, false, 0);
  -- p1 [text L0] William James, the father of American psychology, writing in 1890, felt this view absurd [ref]. I
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"William James, the father of American psychology, writing in 1890, felt this view absurd [ref]. Imagine, he proposed, a litter of dogs raised in the Vatican, marble sculpture presented to their eyes in every conceivable form and combination for generation after generation. If experience alone shaped the mind, these dogs ought eventually to become connoisseurs of sculpture. They do not, he posited, because something selective stands between what the eyes receive and what the mind comes to know."}]}$ob$::jsonb, $ob$William James, the father of American psychology, writing in 1890, felt this view absurd [ref]. Imagine, he proposed, a litter of dogs raised in the Vatican, marble sculpture presented to their eyes…$ob$, 1, false, NULL, NULL, false, 0);
  -- p2 [text L0] As is often the case with science, that “something” had already been caught in the act, twenty-th
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"As is often the case with science, that “something” had already been caught in the act, twenty-three years earlier by the famous German physiologist Hermann von Helmholtz who asked whether attention could move without the eyes moving [ref]. He sat in a darkened room, fixed his gaze on a single point, and arranged a printed sheet of letters in front of him, invisible until a brief electric spark lit the room for an instant — too brief for any eye movement to occur. Before each flash, Helmholtz silently chose where on the sheet he would direct his attention and found the letters readable when the room lit up (well in the afterimage of it anyway). However, other letters, equally close to his fixation point, were lost to him entirely. Helmholtz’s eyes had not moved; only attention had. It seemed that selection was not something that only the eyes could do, rather it seemed the brain could do it independently."}]}$ob$::jsonb, $ob$As is often the case with science, that “something” had already been caught in the act, twenty-three years earlier by the famous German physiologist Hermann von Helmholtz who asked whether attention…$ob$, 2, false, NULL, NULL, false, 0);

  -- Section 2: Attention is measured behaviorally
