  -- p0 [level-1 header] The cocktail party problem
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"heading","level":3,"content":"The cocktail party problem"}]}$ob$::jsonb, $ob$The cocktail party problem$ob$, 0, false, NULL, NULL, true, 1);
  -- p1 [text L1] How do we follow one conversation in a noisy room while ignoring all others — and why does our ow
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"How do we follow one conversation in a noisy room while ignoring all others — and why does our own name, spoken across that room, still catch our attention? This is the cocktail party problem, named by the British engineer Colin Cherry in 1953, and it became the founding question of experimental attention research"},{"type":"citation_ref","number":1},{"type":"text","content":"."}]}$ob$::jsonb, $ob$How do we follow one conversation in a noisy room while ignoring all others — and why does our own name, spoken across that room, still catch our attention? This is the cocktail party problem, named…$ob$, 1, false, NULL, NULL, false, 1);
  -- p2 [text L1] Cherry's method was to present different speech passages simultaneously to each ear through headp
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Cherry's method was to present different speech passages simultaneously to each ear through headphones and ask participants to repeat the message in one ear alone. He called this “shadowing” and participants did this easily but retained almost nothing from the rejected ear even if it switched to a foreign language. It seemed that while the physical properties of the sound crossed into awareness, the meaning did not. Donald Broadbent formalized this in 1958 with the first mechanistic model of selective attention: incoming stimuli are held briefly in a pre-attentive buffer and passed through a bottleneck that passed one channel on the basis of physical features (e.g. <em>pitch, location, voice</em>) and blocked the rest from further processing"},{"type":"citation_ref","number":2},{"type":"text","content":"."}]}$ob$::jsonb, $ob$Cherry's method was to present different speech passages simultaneously to each ear through headphones and ask participants to repeat the message in one ear alone. He called this “shadowing” and…$ob$, 2, false, NULL, NULL, false, 1);
  -- p3 [text L1] Broadbent's all-or-nothing filter did not survive experimental scrutiny. Neville Moray showed tha
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Broadbent's all-or-nothing filter did not survive experimental scrutiny. Neville Moray showed that participants heard their own name on the unattended ear about thirty percent of the time, which an absolute gate cannot explain. In other words, the name must have been recognized as meaningful before it could be privileged"},{"type":"citation_ref","number":3},{"type":"text","content":". Anne Treisman extended this challenge by showing that if the attended and unattended channels swapped mid-stream, participants sometimes continued shadowing a word that had just crossed to the ignored side; bilingual listeners occasionally noticed that the rejected channel carried a translation of what they were attending"},{"type":"citation_ref","number":4},{"type":"text","content":". Treisman proposed that Broadbent’s filter attenuates rather than blocks the unattended channel, with individual words (like names) carrying permanently low recognition thresholds. Yet another proposal suggested that all incoming information reaches full perceptual analysis, and selection operates only at the level of memory and response"},{"type":"citation_ref","number":5},{"type":"text","content":". A more recent aspect of this debate showed that the degree to which unattended information is suppressed scales with the processing demands of the attended task"},{"type":"citation_ref","number":6},{"type":"text","content":". While these studies suggested that attention is graded and capacity-dependent, a major limitation remained: measures of selection were inferred from what a listener did or did not report."}]}$ob$::jsonb, $ob$Broadbent's all-or-nothing filter did not survive experimental scrutiny. Neville Moray showed that participants heard their own name on the unattended ear about thirty percent of the time, which an…$ob$, 3, false, NULL, NULL, false, 1);
  -- p4 [text L1] When listeners fail to report something, its origin is ambiguous. When participants missed their 
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"When listeners fail to report something, its origin is ambiguous. When participants missed their name on the unattended channel 2/3 times, was it because they failed to detect it? Or did it register, but just not enough to cross the threshold for reporting it? To distinguish these scenarios requires signal detection theory."}]}$ob$::jsonb, $ob$When listeners fail to report something, its origin is ambiguous. When participants missed their name on the unattended channel 2/3 times, was it because they failed to detect it? Or did it…$ob$, 4, false, NULL, NULL, false, 1);
  -- p5 [widget psychometric-function] Interactive: The psychometric function
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"widget","widgetId":"psychometric-function","kind":"breakout","title":"The psychometric function","blurb":"Scrub stimulus strength along the detection curve and compare a lower threshold, a liberal bias and a high lapse rate: threshold and bias shift the curve alike, and only the false-alarm rate tells them apart.","credit":"Arjun Krishnaswamy","route":"/psychometric-function","placementId":"attention-psychometric-function"}]}$ob$::jsonb, $ob$Interactive: The psychometric function$ob$, 5, false, NULL, NULL, false, 1);
  -- p6 [text L1] Gustav Fechner's psychophysical methods, set out in 1860, presented a stimulus at a range of inte
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Gustav Fechner's psychophysical methods, set out in 1860, presented a stimulus at a range of intensities and recorded the proportion of trials on which an observer reported detecting it[Fechner 1860, <em>Elemente der Psychophysik</em>]."}]}$ob$::jsonb, $ob$Gustav Fechner's psychophysical methods, set out in 1860, presented a stimulus at a range of intensities and recorded the proportion of trials on which an observer reported detecting it[Fechner…$ob$, 6, false, NULL, NULL, false, 1);
  -- p7 [text L1] Plotted against stimulus strength, those proportions trace a sigmoid curve — the psychometric fun
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Plotted against stimulus strength, those proportions trace a sigmoid curve — the psychometric function — rising from near zero to near one across a narrow band of intensities. Two quantities summarize it: the threshold, conventionally the strength detected on half of trials, and the slope, which describes how abruptly performance changes across that band. Attention experiments adopted the same measurement, treating a leftward shift of the curve as evidence that the attended stimulus had become easier to detect."}]}$ob$::jsonb, $ob$Plotted against stimulus strength, those proportions trace a sigmoid curve — the psychometric function — rising from near zero to near one across a narrow band of intensities. Two quantities…$ob$, 7, false, NULL, NULL, false, 1);
  -- p8 [level-1 header] Signal detection theory
