  -- p43 [text L2] Because the outside stimulus isn't spatially inside the receptive field, it never enters this ne
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Because the outside stimulus isn't spatially inside the receptive field, it never enters this neuron's denominator the way the non-preferred stimulus did in the two-stimuli case. There is no competing term here, nothing being suppressed. The only question is whether the attended orientation matches what this neuron prefers."}]}$ob$::jsonb, $ob$Because the outside stimulus isn't spatially inside the receptive field, it never enters this neuron's denominator the way the non-preferred stimulus did in the two-stimuli case. There is no…$ob$, 43, false, NULL, NULL, false, 2);
