  -- Section 4: Population effects of visual attention
  v_section_id := gen_random_uuid();
  INSERT INTO sections (id, module_id, title, slug, order_index, introduction_text)
  VALUES (v_section_id, v_module_id, $ob$Population effects of visual attention$ob$, $ob$population-effects-of-visual-attention$ob$, 4, NULL);
  -- p0 [level-1 header] Attention improves signal to noise ratio by reducing shared variability among neurons.
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"heading","level":3,"content":"Attention improves signal to noise ratio by reducing shared variability among neurons."}]}$ob$::jsonb, $ob$Attention improves signal to noise ratio by reducing shared variability among neurons.$ob$, 0, false, NULL, NULL, true, 1);
  -- p1 [text L1] Increasing the responsiveness of neurons during attention, carries a hidden cost: a neuron that f
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Increasing the responsiveness of neurons during attention, carries a hidden cost: a neuron that fires more strongly to the attended stimulus also fires more variably from trial to trial. This means that attentional increases in gain apply to signal and noise equally. In principle this need not matter, since the brain could average across many enhanced neurons and thereby reduce noise. However, averaging only works if each neuron's noise is uncorrelated with that of its neighbors. This is not the case for visual neurons, particularly those with overlapped receptive fields which tend to fluctuate together."}]}$ob$::jsonb, $ob$Increasing the responsiveness of neurons during attention, carries a hidden cost: a neuron that fires more strongly to the attended stimulus also fires more variably from trial to trial. This means…$ob$, 1, false, NULL, NULL, false, 1);
  -- p2 [text L1] This shared fluctuation is measured as the noise correlation: the correlation between two neurons
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"This shared fluctuation is measured as the noise correlation: the correlation between two neurons' spike counts across repeated presentations of the same stimulus under the same task conditions. Because the stimulus is identical on every trial, whatever covaries between the two neurons is not stimulus-driven. Since this noise is common to the pair, it survives any subsequent averaging and sets a ceiling on the sensitivity a population can reach."}]}$ob$::jsonb, $ob$This shared fluctuation is measured as the noise correlation: the correlation between two neurons' spike counts across repeated presentations of the same stimulus under the same task conditions.…$ob$, 2, false, NULL, NULL, false, 1);
  -- p3 [text L1] Recent work indicates that attention lowers this ceiling. Recording pairs of V4 neurons during sp
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Recent work indicates that attention lowers this ceiling. Recording pairs of V4 neurons during spatial attention tasks, two groups found that noise correlations fell by roughly 40% when attention was directed into the neurons' shared receptive field (Cohen and Maunsell, 2009; Mitchell, Sundberg, and Reynolds, 2009). This is a much larger effect than attention had on the same neurons' firing rates (under 20%) or on the variability of each neuron considered alone (under 10%)."}]}$ob$::jsonb, $ob$Recent work indicates that attention lowers this ceiling. Recording pairs of V4 neurons during spatial attention tasks, two groups found that noise correlations fell by roughly 40% when attention…$ob$, 3, false, NULL, NULL, false, 1);
  -- p4 [text L1] The size of these three changes maps onto how much each contributes to the population. Cohen and 
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"The size of these three changes maps onto how much each contributes to the population. Cohen and Maunsell (2009) recorded groups of V4 neurons simultaneously and measured how well the population discriminated between two stimuli, then asked which physiological change accounted for the attention-related improvement in that measure. The reduction in noise correlation accounted for over 80% of it. Across recording sessions, the improvement in population sensitivity tracked the improvement in the monkey's psychophysical threshold, though this relationship is correlational; no experiment has yet manipulated noise correlations directly to test whether they cause the behavioral gain."}]}$ob$::jsonb, $ob$The size of these three changes maps onto how much each contributes to the population. Cohen and Maunsell (2009) recorded groups of V4 neurons simultaneously and measured how well the population…$ob$, 4, false, NULL, NULL, false, 1);
  -- p5 [figure 2] Figure 2. Attention and shared variability in V4: the task, and the population's attention axis 
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"figure_placeholder","number":2,"caption":"Attention and shared variability in V4: the task, and the population's attention axis (after Cohen and Maunsell, 2010)."},{"type":"text","content":". Attention and shared variability in V4: the task, and the population's attention axis (after Cohen and Maunsell, 2010)."}]}$ob$::jsonb, $ob$Figure 2. Attention and shared variability in V4: the task, and the population's attention axis (after Cohen and Maunsell, 2010).$ob$, 5, true, v_fig_2, 'auto', false, 1);
  -- p6 [text L1] The same pattern holds for feature attention. Recording V4 populations while monkeys alternated b
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"The same pattern holds for feature attention. Recording V4 populations while monkeys alternated between spatial and feature attention tasks, Cohen and Maunsell (2011a) found that pairs showing the largest rate increases showed the largest correlation decreases, and pairs whose rates fell showed correlations rise instead. Rate and correlation move together in both forms of attention, suggesting that whatever mechanism produces gain also produces decorrelation."}]}$ob$::jsonb, $ob$The same pattern holds for feature attention. Recording V4 populations while monkeys alternated between spatial and feature attention tasks, Cohen and Maunsell (2011a) found that pairs showing the…$ob$, 6, false, NULL, NULL, false, 1);
  -- p7 [level-1 header] Populations of neurons reveal highly dynamic fluctuations in attention state
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"heading","level":3,"content":"Populations of neurons reveal highly dynamic fluctuations in attention state"}]}$ob$::jsonb, $ob$Populations of neurons reveal highly dynamic fluctuations in attention state$ob$, 7, false, NULL, NULL, true, 1);
  -- p8 [text L1] Population-level studies, like those in the previous section, prompted new ways of thinking about
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Population-level studies, like those in the previous section, prompted new ways of thinking about attentional effects. Specifically, researchers began asking whether firing across a population could serve as a trial-to-trial measure of how attention fluctuates."}]}$ob$::jsonb, $ob$Population-level studies, like those in the previous section, prompted new ways of thinking about attentional effects. Specifically, researchers began asking whether firing across a population could…$ob$, 8, false, NULL, NULL, false, 1);
  -- p9 [text L1] The thinking was that simultaneously recorded neurons could supply many measurements of the same 
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"The thinking was that simultaneously recorded neurons could supply many measurements of the same period of time when a subject is attending (or not) to a visual stimulus. If the responses of many neurons are treated as a set of coordinates, each trial becomes a point in a space with one dimension per neuron, and the trials of a given attention condition form a cloud of points within it. An early, elegant example showed that cues directed at two different spatial locations produce point clouds with different centers. Joining these centers with a line defines an attention axis and projecting a single trial's population response onto this line yields one number describing where the population sat between the two attentional states (Cohen and Maunsell, 2010) (Figure XX)."}]}$ob$::jsonb, $ob$The thinking was that simultaneously recorded neurons could supply many measurements of the same period of time when a subject is attending (or not) to a visual stimulus. If the responses of many…$ob$, 9, false, NULL, NULL, false, 1);
  -- p10 [text L1] Since the axis was built from correct trials alone, missed trials served as an independent test 
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Since the axis was built from correct trials alone, missed trials served as an independent test of whether it tracked attention or merely the cue: on missed trials, projections fell closer to the mean of the opposite attention condition, as though attention had drifted to the wrong location. Projections predicted performance more generally as well — when the population indicated attention to the left, the monkey detected most changes on the left and almost none on the right."}]}$ob$::jsonb, $ob$Since the axis was built from correct trials alone, missed trials served as an independent test of whether it tracked attention or merely the cue: on missed trials, projections fell closer to the…$ob$, 10, false, NULL, NULL, false, 1);
  -- p11 [figure 3] Figure 3. The attention network: the frontal eye field, lateral intraparietal and lateral prefr
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"figure_placeholder","number":3,"caption":"The attention network: the frontal eye field, lateral intraparietal and lateral prefrontal cortex, V4 and the pulvinar, with bottom-up and top-down signals."},{"type":"text","content":". The attention network: the frontal eye field, lateral intraparietal and lateral prefrontal cortex, V4 and the pulvinar, with bottom-up and top-down signals."}]}$ob$::jsonb, $ob$Figure 3. The attention network: the frontal eye field, lateral intraparietal and lateral prefrontal cortex, V4 and the pulvinar, with bottom-up and top-down signals.$ob$, 11, true, v_fig_3, 'auto', false, 1);
  -- p12 [text L1] Later work from the same group used this population measure to track spatial and feature attenti
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Later work from the same group used this population measure to track spatial and feature attention simultaneously. Attention axes for spatial attention fluctuated independently in each hemisphere, while those for feature attention were coordinated across both. This is consistent with the effects of spatial and feature attention on individual neurons: spatial attention is localized to neurons representing the attended location, whereas feature attention modulates neurons carrying information about the attended feature regardless of where their receptive fields sit. These differences in cortical extent become relevant when we consider the circuitry that implements attentional effects in the next section."}]}$ob$::jsonb, $ob$Later work from the same group used this population measure to track spatial and feature attention simultaneously. Attention axes for spatial attention fluctuated independently in each hemisphere,…$ob$, 12, false, NULL, NULL, false, 1);

  -- Section 5: Primate studies suggest that brain regions involved in saccade generation and planning are also used for attention
  v_section_id := gen_random_uuid();
  INSERT INTO sections (id, module_id, title, slug, order_index, introduction_text)
  VALUES (v_section_id, v_module_id, $ob$Primate studies suggest that brain regions involved in saccade generation and planning are also used for attention$ob$, $ob$primate-studies-suggest-that-brain-regions-involved-in-saccade-generation-and-planning-are-also-used-for-attention$ob$, 5, NULL);
  -- p0 [level-1 header] Attentional networks
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"heading","level":3,"content":"Attentional networks"}]}$ob$::jsonb, $ob$Attentional networks$ob$, 0, false, NULL, NULL, true, 1);
  -- p1 [text L1] Attention often guides subsequent eye movements (called saccades). A salient object in the periph
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Attention often guides subsequent eye movements (called saccades). A salient object in the periphery is typically fixated within a few hundred milliseconds, and the saccade that brings it to the fovea is ballistic: its endpoint is committed before the movement begins. Selection of a target must therefore be complete before the eyes move, which makes the interval preceding a saccade a window in which attentional signals should already be present."}]}$ob$::jsonb, $ob$Attention often guides subsequent eye movements (called saccades). A salient object in the periphery is typically fixated within a few hundred milliseconds, and the saccade that brings it to the…$ob$, 1, false, NULL, NULL, false, 1);
  -- p2 [text L1] The earliest recordings of attention-related activity exploited exactly this interval. Goldberg a
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"The earliest recordings of attention-related activity exploited exactly this interval. Goldberg and Wurtz (1972) found that visual responses of neurons in the superficial layers of the superior colliculus, a midbrain structure that generates saccades, were larger when the stimulus in the receptive field was about to become the target of an eye movement. The enhancement was spatially specific: it did not occur when the monkey made a saccade elsewhere in the visual field."}]}$ob$::jsonb, $ob$The earliest recordings of attention-related activity exploited exactly this interval. Goldberg and Wurtz (1972) found that visual responses of neurons in the superficial layers of the superior…$ob$, 2, false, NULL, NULL, false, 1);
  -- p3 [text L1] Over the following decades, presaccadic activity became a general assay for attentional signals, 
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Over the following decades, presaccadic activity became a general assay for attentional signals, and the relative timing of that activity across areas became a measure of how attention propagates through the brain. Recordings in the frontal eye field, the lateral intraparietal area, the lateral prefrontal cortex, area V4, and the pulvinar established that each carries signals distinguishing attended from unattended locations, and that these signals differ in latency and in what they encode. Key areas involved in attention include:"}]}$ob$::jsonb, $ob$Over the following decades, presaccadic activity became a general assay for attentional signals, and the relative timing of that activity across areas became a measure of how attention propagates…$ob$, 3, false, NULL, NULL, false, 1);
  -- p4 [text L1] Superior colliculus: Superior colliculus: A midbrain structure involved in multisensory integrati
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"<strong>Superior colliculus:</strong> Superior colliculus: A midbrain structure involved in multisensory integration. The colliculus contains topographic maps that encode visual, auditory, and tactile space, with a deeper layer containing motor neurons involved in generating saccades. Extensive work on this structure shows a role in orienting behaviors, and pioneering work on attention used it to connect neural signals to attention-related effects. Classical and modern studies demonstrate that collicular neurons viewing an attended object often enhance their firing. These responses are not merely correlates: stimulation of the colliculus at currents too weak to evoke a saccade improves discrimination of stimuli at the corresponding location (Cavanaugh and Wurtz, 2004), and transiently inactivating it produces apparent attentional deficits (Zénon and Krauzlis, 2012). In the latter experiment the attention-related enhancement of firing in visual cortex was left intact while behavior deteriorated, indicating that the colliculus contributes to attention through a route that does not pass through the cortical modulation described in earlier sections."}]}$ob$::jsonb, $ob$Superior colliculus: Superior colliculus: A midbrain structure involved in multisensory integration. The colliculus contains topographic maps that encode visual, auditory, and tactile space, with a…$ob$, 4, false, NULL, NULL, false, 1);
  -- p5 [text L1] Visual area V4: Arguable the premier brain area for observing and investigating attentional effec
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"<strong>Visual area V4:</strong> Arguable the premier brain area for observing and investigating attentional effects, this region is part of the so-called ventral stream of the primate visual pathway and contains neurons with large receptive fields (viewing nearly 60 degrees of visual arc) characterized primarily by selectivity for colour, orientation, and shape. Many of the attention effects described in earlier sections (ie: on response/contrast gain, population correlations) were described in this area first and then generalized to other visual regions."}]}$ob$::jsonb, $ob$Visual area V4: Arguable the premier brain area for observing and investigating attentional effects, this region is part of the so-called ventral stream of the primate visual pathway and contains…$ob$, 5, false, NULL, NULL, false, 1);
  -- p6 [text L1] Frontal Eye Fields (FEF): In 1875 David Ferrier reported to the Royal Society that electrical sti
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"<strong>Frontal Eye Fields (FEF):</strong> In 1875 David Ferrier reported to the Royal Society that electrical stimulation of a small region of the monkey frontal lobe turned the eyes and head to the opposite side. That region, the FEF, is still identified as the part of prefrontal cortex where low currents evoke short-latency saccades (Robinson and Fuchs, 1969). Unilateral lesions produce a complementary deficit, leaving animals ignoring objects in the contralateral field as though they were unable to attend to these stimuli. The intervening years have still not been able to resolve FEF’s role as a saccade-generating area or an attention area and it contains neurons with preferences for visual, auditory, and sometimes tactile stimuli and effects on eye movement. It also has strong reciprocal connections with many lower structures, including area V4, where many attention-related changes in neural firing have been documented. Microstimulation studies using current intensities too low to evoke saccades enhance V4 neuron firing in ways that resemble attention."}]}$ob$::jsonb, $ob$Frontal Eye Fields (FEF): In 1875 David Ferrier reported to the Royal Society that electrical stimulation of a small region of the monkey frontal lobe turned the eyes and head to the opposite side.…$ob$, 6, false, NULL, NULL, false, 1);
  -- p7 [text L1] Lateral intraparietal cortex (LIP): A region on the lateral bank of the intraparietal sulcus in p
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"<strong>Lateral intraparietal cortex (LIP):</strong> A region on the lateral bank of the intraparietal sulcus in posterior parietal cortex, reciprocally connected with the frontal eye field, the superior colliculus, and extrastriate visual cortex. It contains a topographic map of contralateral space in eye-centered coordinates, and saccades can be evoked from it by electrical stimulation, though at higher currents and longer latencies than in FEF. Its neurons respond to visual stimuli that are either physically salient or relevant to the task, and not to stimuli that are equally visible but of no consequence (Gottlieb, Kusunoki and Goldberg, 1998), so the activity across the map is better described as a representation of behavioral priority than of the image. The peak of that activity tracks where attention is deployed and predicts performance on a discrimination made at that location (Bisley and Goldberg, 2003). LIP differs from the colliculus and FEF in one respect that bears directly on the assay used throughout this section: enhancement of its visual responses occurs whether or not the monkey subsequently makes a saccade to the stimulus (Bushnell, Goldberg and Robinson, 1981). Inactivating LIP slows the detection of targets in the contralateral field even when eye movements are not permitted (Wardak et al., 2004)."}]}$ob$::jsonb, $ob$Lateral intraparietal cortex (LIP): A region on the lateral bank of the intraparietal sulcus in posterior parietal cortex, reciprocally connected with the frontal eye field, the superior colliculus,…$ob$, 7, false, NULL, NULL, false, 1);
  -- p8 [text L1] Lateral Prefrontal Cortex: The cortex lying anterior and ventral to the frontal eye field, encomp
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"<strong>Lateral Prefrontal Cortex:</strong> The cortex lying anterior and ventral to the frontal eye field, encompassing the principal sulcus and the inferior convexity. Unlike the colliculus and FEF, it contains no topographic map of space and no site from which saccades can be evoked; its neurons instead encode the rules and goals of the current task, including which objects are worth finding. This makes it a candidate source for the signals that direct attention rather than a site where attentional modulation is read out. Neurons in the ventral prearcuate region respond selectively to the cue specifying a search target, maintain that selectivity across the delay and across intervening saccades, and discriminate the target in their receptive fields earlier than neurons in FEF or inferotemporal cortex do (Bichot et al., 2015). Inactivating the region impairs the animal's ability to find targets and abolishes the effects of feature attention in FEF while leaving spatial attention there unaffected, indicating that information about what to look for and information about where to look arrive in FEF by separate routes."}]}$ob$::jsonb, $ob$Lateral Prefrontal Cortex: The cortex lying anterior and ventral to the frontal eye field, encompassing the principal sulcus and the inferior convexity. Unlike the colliculus and FEF, it contains no…$ob$, 8, false, NULL, NULL, false, 1);
  -- p9 [text L1] Pulvinar nucleus of the thalamus: The largest nucleus of the primate thalamus, occupying its post
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"<strong>Pulvinar nucleus of the thalamus:</strong> The largest nucleus of the primate thalamus, occupying its posterior pole and reciprocally connected with nearly every visual cortical area as well as with parietal and frontal cortex. It receives ascending input from the superior colliculus, which places it on a subcortical route by which collicular signals can reach cortex without passing through the geniculostriate pathway. Its ventrolateral division connects to ventral stream areas that support object recognition, including V4 and inferotemporal cortex. Pulivinar neurons carry spatial attention signals that largely mirror those of the cortical areas supplying their input, so the pulvinar is not an independent source of attentional modulation. Its contribution appears instead to lie in coordinating activity between the cortical areas it connects: ventrolateral pulvinar inactivation reduces both the attentional enhancement of V4 neuron firing and synchrony and produces severe behavioral deficits in the affected part of the visual field (Zhou, Schafer and Desimone, 2016)."}]}$ob$::jsonb, $ob$Pulvinar nucleus of the thalamus: The largest nucleus of the primate thalamus, occupying its posterior pole and reciprocally connected with nearly every visual cortical area as well as with parietal…$ob$, 9, false, NULL, NULL, false, 1);
  -- p10 [text L1] Other areas: While the above areas are the most prominent, attentional effects in many other bra
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"<strong>Other areas:</strong> While the above areas are the most prominent, attentional effects in many other brain regions have been observed. These include effects in the dorsal lateral geniculate nucleus, the primary visual cortex, area MT, XX, YY, ZZ."}]}$ob$::jsonb, $ob$Other areas: While the above areas are the most prominent, attentional effects in many other brain regions have been observed. These include effects in the dorsal lateral geniculate nucleus, the…$ob$, 10, false, NULL, NULL, false, 1);
  -- p11 [text L1] Whether attention emerges sequentially through this network or appears across all areas is not c
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"<strong>Whether attention emerges sequentially through this network or appears across all areas is not clear.</strong> The areas above were characterized largely one at a time, which leaves open whether attentional signals arrive in them in a fixed order. In pop-out search, target selection emerges at broadly similar times across the network: responses in the frontal eye field, LIP, and the superior colliculus begin as an indiscriminate volley to whatever falls in the receptive field, and only after roughly 130 to 140 milliseconds does firing distinguish the target from the distractors (Thompson et al., 1996; McPeek and Keller, 2002; Ipata et al., 2006). Selection is therefore better described as a change of state that the connected areas undergo together than as a signal relayed from one to the next. Whether any area consistently leads remains contested. Buschman and Miller (2007) reported that prefrontal neurons signalled the target before parietal neurons when search was difficult, with the order reversed when the target was salient, though both the latencies and the analysis have been disputed (Schall, Paré and Woodman, 2007). A clear picture of how these various areas activate over time has not resolved."}]}$ob$::jsonb, $ob$Whether attention emerges sequentially through this network or appears across all areas is not clear. The areas above were characterized largely one at a time, which leaves open whether attentional…$ob$, 11, false, NULL, NULL, false, 1);
  -- p12 [text L1] Are premotor signals and attention the same? The subthreshold stimulation results described abov
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"<strong>Are premotor signals and attention the same?</strong> The subthreshold stimulation results described above set a limit on the motor interpretation. Currents too weak to evoke a movement enhance sensory responses and improve discrimination at the corresponding location, in both the frontal eye field and the superior colliculus, so the modulation does not require a saccade to be executed. It does not follow that attention is independent of the machinery that prepares one. Rizzolatti's premotor theory takes the stronger position that orienting attention is the preparation of a movement that is then withheld, on which reading the stimulation results are expected rather than surprising. Distinguishing that account from one in which the two processes merely share circuitry requires removing saccade preparation while leaving attention intact, which no available manipulation does cleanly."}]}$ob$::jsonb, $ob$Are premotor signals and attention the same? The subthreshold stimulation results described above set a limit on the motor interpretation. Currents too weak to evoke a movement enhance sensory…$ob$, 12, false, NULL, NULL, false, 1);

