  -- p1 [widget corbetta-pet-attention] Interactive: Attention selects visual cortex (Corbetta PET)
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"widget","widgetId":"corbetta-pet-attention","kind":"breakout","title":"Attention selects visual cortex (Corbetta PET)","blurb":"The display stays the same; attending to shape, colour or velocity lights up different PET foci over posterior cortex (Corbetta et al., 1990).","credit":"Arjun Krishnaswamy","route":"/corbetta-pet","placementId":"attention-corbetta-pet-attention"}]}$ob$::jsonb, $ob$Interactive: Attention selects visual cortex (Corbetta PET)$ob$, 1, false, NULL, NULL, false, 0);
