  -- Section 8: Disease
  v_section_id := gen_random_uuid();
  INSERT INTO sections (id, module_id, title, slug, order_index, introduction_text)
  VALUES (v_section_id, v_module_id, $ob$Disease$ob$, $ob$disease$ob$, 8, NULL);
  -- p0 [text L0] Several neurodegenerative and neurodevelopmental diseases disrupt a person's ability to attend, b
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Several neurodegenerative and neurodevelopmental diseases disrupt a person's ability to attend, but drawing a clean line between a particular attentional deficit and a particular brain region has proven difficult — likely because, as reviewed above, so many areas contribute to attention. Two examples illustrate the point. The first is a well-characterized condition that follows damage to the posterior parietal lobes, most often as a consequence of stroke. The second is a common developmental disorder of attention and hyperactivity whose relationship to the circuitry described above remains far less settled."}]}$ob$::jsonb, $ob$Several neurodegenerative and neurodevelopmental diseases disrupt a person's ability to attend, but drawing a clean line between a particular attentional deficit and a particular brain region has…$ob$, 0, false, NULL, NULL, false, 0);
  -- p1 [text L0] Parietal Damage and hemifield neglect: One of the first clues to what posterior parietal cortex d
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"<strong>Parietal Damage and hemifield neglect:</strong> One of the first clues to what posterior parietal cortex does for attention and action came not from the laboratory but from the clinic. In 1909, the Austro-Hungarian physician Rezső Bálint described patients with bilateral damage to posterior parietal and adjacent visual-association cortex who presented a striking trio of deficits: simultanagnosia, an inability to perceive more than one object in the visual field at a time; ocular apraxia, difficulty directing gaze to a chosen target; and optic ataxia, an inability to reach accurately for an object under visual guidance. A patient with optic ataxia could look directly at a cup, name it, and describe it, yet fail to shape the hand correctly to grasp it. Bálint's syndrome — as the triad came to be known — showed that posterior parietal cortex does not merely register where things are; it is what turns that spatial information into a target for gaze and for the hand."}]}$ob$::jsonb, $ob$Parietal Damage and hemifield neglect: One of the first clues to what posterior parietal cortex does for attention and action came not from the laboratory but from the clinic. In 1909, the…$ob$, 1, false, NULL, NULL, false, 0);
  -- p2 [figure 4] Figure 4. Parietal damage and neglect: a patient's copies of drawings, and a right inferior pari
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"figure_placeholder","number":4,"caption":"Parietal damage and neglect: a patient's copies of drawings, and a right inferior parietal lesion."},{"type":"text","content":". Parietal damage and neglect: a patient's copies of drawings, and a right inferior parietal lesion."}]}$ob$::jsonb, $ob$Figure 4. Parietal damage and neglect: a patient's copies of drawings, and a right inferior parietal lesion.$ob$, 2, true, v_fig_4, 'auto', false, 0);
  -- p3 [text L0] Unilateral damage to the same broad region produces a related but distinct syndrome, confined to 
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Unilateral damage to the same broad region produces a related but distinct syndrome, confined to one side of space rather than global. Patients with hemispatial neglect — most often following right-hemisphere damage — fail to attend, respond, or orient to the side of space opposite the lesion, despite intact primary visual pathways and intact motor control. They eat from only one side of a plate, groom only one side of the face, and copy only one side of a line drawing; on formal testing, they bisect a line well to the right of its true midpoint and, on cancellation tasks, mark targets on the ipsilesional side while leaving the other untouched. One influential account holds that the core deficit is an inability to disengage attention already captured on the intact side in order to redirect it toward the neglected one (Posner et al., 1984) — consistent with, though not the sole explanation for, the syndrome's classic association with lesions of the right inferior parietal lobule and temporoparietal junction (Vallar &amp; Perani, 1986)."}]}$ob$::jsonb, $ob$Unilateral damage to the same broad region produces a related but distinct syndrome, confined to one side of space rather than global. Patients with hemispatial neglect — most often following…$ob$, 3, false, NULL, NULL, false, 0);
  -- p4 [text L0] Attention Deficit Hyperactivity Disorder: Attention-deficit/hyperactivity disorder (ADHD) is a co
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"<strong>Attention Deficit Hyperactivity Disorder:</strong> Attention-deficit/hyperactivity disorder (ADHD) is a common neurodevelopmental condition, affecting roughly 5% of children and persisting into adulthood in a substantial fraction of cases, characterized by inattention, hyperactivity, and impulsivity. It is heritable (twin studies put heritability near 80%) but polygenic, with genome-wide association studies implicating dozens of common variants of individually small effect rather than a single causal gene. Neuroimaging studies suggest under-activation of dorsolateral prefrontal cortex during attention and working-memory tasks, and altered resting-state patterns in the dorsal and ventral attention networks. However, this correspondence is coarse because of the wildly differing scales of neuromimaging and neurophysiological techniques. Effect sizes are small, and no structural or functional marker reliably distinguishes individuals with ADHD from those without. Behavioral tests of the kind described earlier in this chapter nonetheless reveal clear attentional dysfunction in individuals with ADHD. Refining those observations and connecting them to activity in attention-related brain areas, remains an open direction for future work."}]}$ob$::jsonb, $ob$Attention Deficit Hyperactivity Disorder: Attention-deficit/hyperactivity disorder (ADHD) is a common neurodevelopmental condition, affecting roughly 5% of children and persisting into adulthood in…$ob$, 4, false, NULL, NULL, false, 0);

