  -- p0 [list L0] Cherry E.C. (1953). Some Experiments on the Recognition of Speech, with One and with Two Ears. Th
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"list","ordered":true,"items":["Cherry E.C. (1953). Some Experiments on the Recognition of Speech, with One and with Two Ears. <em>The Journal of the Acoustical Society of America</em> 25, 975-979. https://doi.org/10.1121/1.1907229","Broadbent D.E. (1958). Perception and communication. <em>Pergamon Press</em>. https://doi.org/10.1037/10037-000","Moray N. (1959). Attention in Dichotic Listening: Affective Cues and the Influence of Instructions. <em>Quarterly Journal of Experimental Psychology</em> 11, 56-60. https://doi.org/10.1080/17470215908416289","Treisman A.M. (1960). Contextual Cues in Selective Listening. <em>Quarterly Journal of Experimental Psychology</em> 12, 242-248. https://doi.org/10.1080/17470216008416732","Deutsch J.A., Deutsch D. (1963). Attention: Some theoretical considerations. <em>Psychological Review</em> 70, 80-90. https://doi.org/10.1037/h0039515","Lavie N. (1995). Perceptual load as a necessary condition for selective attention. <em>Journal of Experimental Psychology: Human Perception and Performance</em> 21, 451-468. https://doi.org/10.1037/0096-1523.21.3.451","Tanner W.P., Swets J.A. (1954). A decision-making theory of visual detection. <em>Psychological Review</em> 61, 401-409. https://doi.org/10.1037/h0058700","Posner M.I., Snyder C.R., Davidson B.J. (1980). Attention and the detection of signals. <em>Journal of Experimental Psychology</em> 109, 160-174.","Bashinski H.S., Bacharach V.R. (1980). Enhancement of perceptual sensitivity as the result of selectively attending to spatial locations. <em>Perception &amp; Psychophysics</em> 28, 241-248. https://doi.org/10.3758/BF03204380"]}]}$ob$::jsonb, $ob$Cherry E.C. (1953). Some Experiments on the Recognition of Speech, with One and with Two Ears. The Journal of the Acoustical Society of America 25, 975-979. https://doi.org/10.1121/1.1907229…$ob$, 0, false, NULL, NULL, false, 0);

