  {
    "src": "/publicAssets/images/attention/cohen-maunsell-2010-task.png",
    "alt": "The task: a monkey fixates while stimuli appear left and right, one of them cued."
  },
  {
    "src": "/publicAssets/images/attention/cohen-maunsell-2010-attention-axis.png",
    "alt": "Population responses projected onto the attention axis, separating attend-left from attend-right trials."
  }
]$t$::jsonb
  )
where animation_key = 'animationAttentionV2Fig2';

update public.animations
set
  title = $t$The attention network$t$,
  image_file_url = '/publicAssets/images/attention/attention-network-brain-cartoon.jpeg',
  config = (config - 'note') || jsonb_build_object(
    'caption', $t$The attention network: the frontal eye field, lateral intraparietal and lateral prefrontal cortex, V4 and the pulvinar, with bottom-up and top-down signals.$t$,
    'images', $t$[
  {
    "src": "/publicAssets/images/attention/attention-network-brain-cartoon.jpeg",
    "alt": "A brain cartoon with the attention areas labelled and arrows for bottom-up and top-down signals."
  }
]$t$::jsonb
  )
where animation_key = 'animationAttentionV2Fig3';

update public.animations
set
  title = $t$Parietal damage and neglect$t$,
  image_file_url = '/publicAssets/images/attention/neglect-copying-drawings.png',
  config = (config - 'note') || jsonb_build_object(
    'caption', $t$Parietal damage and neglect: a patient's copies of drawings, and a right inferior parietal lesion.$t$,
    'images', $t$[
  {
    "src": "/publicAssets/images/attention/neglect-copying-drawings.png",
    "alt": "A patient's copies of a clock, a house and a flower, missing their left halves."
  },
  {
    "src": "/publicAssets/images/attention/neglect-right-ipl-lesion.png",
    "alt": "Brain images showing a lesion in the right inferior parietal lobe."
  }
]$t$::jsonb
  )
where animation_key = 'animationAttentionV2Fig4';

-- Check.
do $$
declare
  m uuid := (select id from public.modules where slug = 'attention-and-working-memory');
  n int;
begin
  if m is null then
    raise exception 'attention: the chapter was not seeded';
  end if;
  if (select ramp from public.modules where id = m) is distinct from 'lear' then
    raise exception 'attention: the chapter has no subject ramp';
  end if;
  select count(*) into n from public.sections where module_id = m;
  if n <> 10 then
    raise exception 'attention: % sections, expected 10', n;
  end if;
  select count(*) into n
    from public.paragraphs p join public.sections s on s.id = p.section_id,
    jsonb_array_elements(p.content -> 'blocks') b
   where s.module_id = m and b ->> 'type' = 'widget';
  if n <> 9 then
    raise exception 'attention: % widgets, expected 9', n;
  end if;
  select count(*) into n from public.animations
   where animation_key like 'animationAttentionV2Fig%' and config ? 'images';
  if n <> 4 then
    raise exception 'attention: % of 4 figures have artwork', n;
  end if;
end $$;

COMMIT;
